const data = $json;

function clean(value) {
  return String(value ?? '').trim();
}

const client_name = clean(data.client_name);
const email = clean(data.email).toLowerCase();
const hotel_name = clean(data.hotel_name);
const room_type = clean(data.room_type);
const date_from = clean(data.date_from);
const date_to = clean(data.date_to);

const errors = [];

if (!client_name) errors.push('Не указано имя клиента');
if (!email) errors.push('Не указан email');
if (!hotel_name) errors.push('Не указан отель');
if (!room_type) errors.push('Не указан тип номера');
if (!date_from) errors.push('Не указана дата заезда');
if (!date_to) errors.push('Не указана дата выезда');

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (email && !emailValid) {
  errors.push('Некорректный email');
}

if (date_from && date_to) {
  const from = new Date(date_from);
  const to = new Date(date_to);

  if (isNaN(from.getTime())) errors.push('Некорректная дата заезда');
  if (isNaN(to.getTime())) errors.push('Некорректная дата выезда');

  if (!isNaN(from.getTime()) && !isNaN(to.getTime()) && from >= to) {
    errors.push('Дата выезда должна быть позже даты заезда');
  }
}

const booking_id = 'B-' + Date.now();

return {
  json: {
    booking_id,
    client_name,
    email,
    hotel_name,
    room_type,
    date_from,
    date_to,
    status: errors.length === 0 ? 'new' : 'error',
    payment_status: 'waiting',
    created_at: new Date().toISOString(),
    validation_ok: errors.length === 0,
    validation_errors: errors.join('; ')
  }
};

const request = $('01 Prepare and Validate Request').first().json;
const rooms = $('03 Read Rooms').all().map(item => item.json);
const bookings = $('03B Read Bookings').all().map(item => item.json);

function clean(value) {
  return String(value ?? '').trim();
}

function dateOnly(value) {
  return clean(value).slice(0, 10);
}

function getNights(dateFrom, dateTo) {
  const from = new Date(`${dateOnly(dateFrom)}T00:00:00Z`);
  const to = new Date(`${dateOnly(dateTo)}T00:00:00Z`);

  const diffMs = to.getTime() - from.getTime();
  const nights = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

  return nights > 0 ? nights : 0;
}

// Проверяем пересечение двух периодов.
// Если один клиент выезжает 20-го, другой может заехать 20-го.
function datesOverlap(start1, end1, start2, end2) {
  const s1 = dateOnly(start1);
  const e1 = dateOnly(end1);
  const s2 = dateOnly(start2);
  const e2 = dateOnly(end2);

  if (!s1 || !e1 || !s2 || !e2) {
    return false;
  }

  return s1 < e2 && e1 > s2;
}

function bookingBlocksRoom(booking) {
  const status = clean(booking.status).toLowerCase();

  // Эти записи не должны блокировать номер.
  return ![
    '',
    'cancelled',
    'canceled',
    'error',
    'not_available'
  ].includes(status);
}

const requestDateFrom = dateOnly(request.date_from);
const requestDateTo = dateOnly(request.date_to);

const nights = getNights(requestDateFrom, requestDateTo);

const suitableRoom = rooms.find(room => {
  const sameHotel =
    clean(room.hotel_name) === clean(request.hotel_name);

  const sameType =
    clean(room.room_type) === clean(request.room_type);

  // Если в Rooms указан период доступности номера,
  // запрашиваемые даты должны попадать внутрь него.
  const roomDateFrom = dateOnly(room.date_from);
  const roomDateTo = dateOnly(room.date_to);

  const roomPeriodFits =
    (!roomDateFrom || roomDateFrom <= requestDateFrom) &&
    (!roomDateTo || roomDateTo >= requestDateTo);

  if (!sameHotel || !sameType || !roomPeriodFits) {
    return false;
  }

  // Проверяем, есть ли активная бронь этого номера
  // с пересечением дат.
  const hasConflict = bookings.some(booking => {
    const sameRoom =
      clean(booking.room_id) === clean(room.room_id);

    if (!sameRoom || !bookingBlocksRoom(booking)) {
      return false;
    }

    return datesOverlap(
      booking.date_from,
      booking.date_to,
      requestDateFrom,
      requestDateTo
    );
  });

  return !hasConflict;
});

if (!suitableRoom) {
  return [
    {
      json: {
        ...request,
        room_found: false,
        room_id: '',
        price_per_night: '',
        nights,
        total_price: '',
        status: 'not_available',
        message: 'Свободный номер по выбранным параметрам и датам не найден'
      }
    }
  ];
}

const price_per_night = Number(suitableRoom.price);
const total_price = price_per_night * nights;

return [
  {
    json: {
      ...request,
      room_found: true,
      room_id: suitableRoom.room_id,
      price_per_night,
      nights,
      total_price,
      status: 'reserved',
      message: 'Свободный номер найден'
    }
  }
];
